void mainImage(out vec4 fragColor, vec2 fragCoord)
{
    float dt = .02, N = fract(iTime / 20.) * 20. * 60. / dt, i = 0.;
    vec4 Q = vec4(.1, 0, 0, 1), m = vec4(0);
    vec3 C = vec3(1);
    vec2 R = iResolution.xy;

    if (iMouse.z > 0.)
        m.yw = (iMouse.xy - R / 2.) / R.y / .3;

    for ( ; i<N ; i++)
    {
        if (i > N - 5.7 / dt)
            C -= dt * exp(4. - length(fragCoord - R / 2. - Q.yw * R.y * .3));
        Q.yw +=      Q                                  .xz * dt;
        Q.xz += (m - Q - Q * exp(-dot(Q.yw, Q.yw)) / 2.).yw * dt;

        float H = dot(Q.xz, Q.xz) / 2. + -dot(m.yw, Q.yw) + dot(Q.yw, Q.yw) / 2. + (1. - exp(-dot(Q.yw, Q.yw))) / 4.;
        if (i > N - 60. / dt)
            C -= dt * exp(2.-length(fragCoord - R * vec2(fract(i*dt/60.), .1 + .1 * H)));
    }

    // H(x, v) = V(x) + T(v)
    // dx =  dT(v) -> dT(v) =      v                          , T(0) = 0 -> T(v) =              dot(v, v) / 2
    // dv = -dV(x) -> dV(x) = -m + x + x * exp(-dot(x, x)) / 2, V(0) = 0 -> V(x) = -dot(m, x) + dot(x, x) / 2 + (1 - exp(-dot(x, x))) / 4
    //
    // Computing V(x) from dV(x) can be done by integrating along axis aligned segments:
    //   dV(x)[0] from (0   , 0) to (x[0], 0   )
    //   dV(x)[1] from (x[0], 0) to (x[0], x[1])

    fragColor = vec4(sqrt(C), 1);
}
